import {programs,clone,localDate,freshState,countSets,completedSets,validateBackup,validDate,mergeHistory,createWorkout,exercise} from './model.js';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,state=freshState(),storageOK=false,writeQueue=Promise.resolve(),restUntil=0,toastTimer;
const uid=()=>crypto.randomUUID();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function storageError(){storageOK=false;$('.local-badge').innerHTML='<span style="color:#a53728">Not saved · export a backup</span>';toast('Storage is unavailable. Export a backup before leaving.');}
function save(){const snapshot=clone(state);writeQueue=writeQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db)return reject(Error('No storage'));const tx=db.transaction('notebook','readwrite');tx.objectStore('notebook').put(snapshot,'state');tx.oncomplete=()=>{storageOK=true;resolve();};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}));writeQueue.catch(storageError);return writeQueue;}
async function openDB(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('lift-log',1);r.onupgradeneeded=()=>r.result.createObjectStore('notebook');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Close other Lift Log tabs'));});const value=await new Promise((resolve,reject)=>{const tx=db.transaction('notebook');const r=tx.objectStore('notebook').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(value)state=validateBackup(value);storageOK=true;db.onversionchange=()=>{db.close();storageError();};}catch{storageError();}}
const fmtDate=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const sortedHistory=()=>[...state.history].sort((a,b)=>b.date.localeCompare(a.date));
const latestExercise=e=>sortedHistory().flatMap(w=>w.exercises).find(p=>p.name.toLowerCase()===e.name.toLowerCase()&&p.mode===e.mode&&p.sets.some(s=>s.done));
const setText=(e,s)=>e.mode==='bodyweight'&&s.weight===''?`${s.reps} reps`:`${s.weight||'—'} lb${e.mode==='assistance'?' assist':''} × ${s.reps||'—'}`;
function nextProgram(){const last=sortedHistory().find(w=>w.programId);return programs[(programs.findIndex(p=>p.id===last?.programId)+1)%4];}
function card(p,i){return `<article class="card workout-card"><div class="section-top"><span class="eyebrow" style="margin:0">${p.day} · ${countSets(p)} SETS</span><span class="card-number">0${i+1}</span></div><div><h3>${p.name}</h3><p class="subtle">${p.focus}</p></div><p class="hint">${p.exercises.map(e=>esc(e.name)).join(' / ')}</p><button class="secondary" data-action="start" data-id="${p.id}">Start ${p.name} ↗</button></article>`;}
function today(){const p=nextProgram(),draft=state.draft;const week=new Date();week.setHours(0,0,0,0);week.setDate(week.getDate()-((week.getDay()+6)%7));const weekly=state.history.filter(w=>w.date>=localDate(week)&&w.date<=localDate());return `<p class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p><h1>Strength for<br>the long run.</h1><p class="subtle">Your personal training journal. Built around your four-day split.</p><div class="stats"><div class="stat"><strong>${weekly.length}<span style="font:18px Georgia;color:#a0a99a"> / 4</span></strong><span>Sessions this week</span></div><div class="stat"><strong>${weekly.reduce((n,w)=>n+completedSets(w),0)}</strong><span>Sets logged this week</span></div><div class="stat"><strong>${state.history.length}</strong><span>Total sessions</span></div></div><section class="hero"><div><p class="eyebrow">${draft?'PICK UP WHERE YOU LEFT OFF':'NEXT IN YOUR ROTATION'}</p><h2>${esc(draft?.name||p.name)}</h2><p class="subtle">${draft?`${completedSets(draft)} of ${countSets(draft)} sets checked · ${fmtDate(draft.date)}`:p.focus}</p><div class="chips"><span class="chip">${countSets(draft||p)} working sets</span><span class="chip">${(draft||p).exercises.length} exercises</span></div></div><span class="hero-number">${draft?'↗':'0'+(programs.indexOf(p)+1)}</span><button data-action="${draft?'resume':'start'}" data-id="${p.id}">${draft?'Resume session':'Start workout'} ↗</button></section><div class="section-top"><h2>Make it your week</h2><span class="hint" style="margin:0">Upper / Lower / Rest / Upper / Lower</span></div><div class="grid">${programs.map(card).join('')}</div>`;}
function program(){return `<p class="eyebrow">THE PLAN</p><h1>Less volume.<br>More intention.</h1><p class="subtle">48 working sets per week. Four direct sets each for biceps and triceps.</p><div class="note">Warm up before working sets. Keep 1–2 good reps in reserve. Rest 2–3 minutes on compound lifts and 60–120 seconds on accessories.</div><div class="grid">${programs.map((p,i)=>`<section class="card"><div class="section-top" style="margin:0 0 15px"><div><p class="eyebrow">${p.day} · ${countSets(p)} WORKING SETS</p><h2>${p.name}</h2><p class="hint">${p.focus}</p></div><span class="card-number">0${i+1}</span></div><ul class="exercise-list">${p.exercises.map(e=>`<li>${e.name}<span>${e.sets.length} × ${e.min}–${e.max}</span></li>`).join('')}</ul><button class="secondary finish" data-action="start" data-id="${p.id}">Start ${p.name} ↗</button></section>`).join('')}</div><div class="note">When all sets reach the top of the rep range with clean technique and 1–2 reps left, add the smallest weight increment next time. For assisted pull-ups, reduce assistance. Split-squat sets include both legs; dumbbell weights are per hand.</div>`;}
function session(){const w=state.draft;if(!w){location.hash='today';return '';}return `<div class="session-header"><div><p class="eyebrow">YOUR SESSION · ${storageOK?'AUTOSAVES ON THIS DEVICE':'STORAGE UNAVAILABLE'}</p><h1>${esc(w.name)}</h1></div><button class="secondary icon" data-action="leave" aria-label="Back to Train">←</button></div><div class="session-meta"><label>Date<input type="date" id="workout-date" value="${esc(w.date)}" required></label><label>Session name<input id="workout-name" maxlength="100" value="${esc(w.name)}"></label></div><div class="section-top"><span class="subtle" id="set-count">${completedSets(w)} / ${countSets(w)} sets checked</span><span class="badge">lb</span></div><div class="progress"><div id="progress-bar" style="width:${completedSets(w)/Math.max(1,countSets(w))*100}%"></div></div><div class="timer"><span>Rest <strong id="rest-time">${timerText()}</strong></span><div class="button-row"><button class="secondary" data-action="timer" data-seconds="90">90s</button><button class="secondary" data-action="timer" data-seconds="180">3m</button><button class="secondary" data-action="timer" data-seconds="0" aria-label="Stop rest timer">×</button></div></div>${w.exercises.map((e,i)=>{const last=latestExercise(e);return `<section class="card exercise"><div class="section-top"><div><h3>${esc(e.name)}</h3><p class="hint">${e.min}–${e.max} reps${e.note?' · '+esc(e.note):''}</p></div><button class="text-button" data-action="remove-exercise" data-e="${i}" aria-label="Remove ${esc(e.name)}">Remove</button></div>${last?`<p class="previous">Last: ${last.sets.filter(s=>s.done).map(s=>esc(setText(last,s))).join(' · ')}</p>`:''}<div class="set-head"><span>Set</span><span>${e.mode==='assistance'?'Assistance · lb':e.mode==='bodyweight'?'Added lb (optional)':'Weight · lb'}</span><span>Reps</span><span>Done</span></div>${e.sets.map((s,j)=>`<div class="set-row ${s.done?'completed':''}"><span class="set-no">${j+1}</span><input aria-label="${esc(e.name)} set ${j+1} ${e.mode==='assistance'?'assistance':'weight'} in pounds" inputmode="decimal" type="number" min="0" max="10000" step="0.5" placeholder="${e.mode==='bodyweight'?'BW':'lb'}" value="${esc(s.weight)}" data-e="${i}" data-s="${j}" data-field="weight"><input aria-label="${esc(e.name)} set ${j+1} reps" inputmode="numeric" type="number" min="1" max="10000" step="1" placeholder="${e.min}–${e.max}" value="${esc(s.reps)}" data-e="${i}" data-s="${j}" data-field="reps"><button class="check" aria-label="${esc(e.name)} set ${j+1} complete" aria-pressed="${s.done}" data-action="check" data-e="${i}" data-s="${j}">✓</button></div>`).join('')}<div class="button-row"><button class="text-button" data-action="add-set" data-e="${i}">+ Add set</button>${e.sets.length>1?`<button class="text-button" data-action="remove-set" data-e="${i}">Remove last set</button>`:''}</div></section>`;}).join('')}<button class="secondary" data-action="add-exercise">+ Add exercise</button><label style="margin-top:24px">Session notes<textarea id="session-notes" maxlength="50000" placeholder="How did it feel? Any adjustments?">${esc(w.notes)}</textarea></label><button class="finish" data-action="finish">Finish & save session ↗</button><p class="hint">Check completed sets before finishing. Unchecked sets stay in your record as unfinished.</p><button class="text-button" data-action="discard">Discard this draft</button>`;}
function history(){const list=sortedHistory();return `<p class="eyebrow">THE WORK YOU PUT IN</p><h1>Your training,<br>on record.</h1><p class="subtle">${list.length} saved sessions · stored on this device.</p>${!list.length?`<div class="card empty"><div class="symbol">↶</div><h2>A fresh page.</h2><p class="subtle">Finish your first session, or import your previous workouts from Settings.</p><a href="#settings">Import a backup →</a></div>`:list.map(w=>`<details class="card history-item"><summary><div><h3>${esc(w.name)}</h3><p>${fmtDate(w.date)} · ${completedSets(w)} completed sets</p></div><span aria-hidden="true">＋</span></summary><div class="history-detail">${w.exercises.map(e=>`<p><strong>${esc(e.name)}</strong><br>${e.sets.map((s,i)=>`${i+1}. ${esc(setText(e,s))}${s.done?' ✓':' (not marked complete)'}`).join('<br>')}${e.note?'<br>'+esc(e.note):''}</p>`).join('')}${w.notes?`<p>${esc(w.notes)}</p>`:''}<div class="button-row"><button class="secondary" data-action="edit" data-id="${esc(w.id)}">Edit session</button><button class="danger" data-action="delete" data-id="${esc(w.id)}">Delete</button></div></div></details>`).join('')}`;}
function settings(){return `<p class="eyebrow">MAKE YOURSELF AT HOME</p><h1>Your notebook.<br>Your device.</h1><p class="subtle">Workout records stay in this browser’s storage. No workout data is sent to a server.</p><section class="card settings-card"><h2>Keep a copy in Files</h2><p>Export a JSON backup of your history and current draft. On iPhone, choose “Save to Files” in the share sheet. Import it here to restore or move your notebook to another device.</p><div class="button-row"><button data-action="export">Export backup ↗</button><button class="secondary" data-action="import">Import backup</button></div><input class="backup-input" id="backup-file" type="file" accept=".json,application/json"><p class="hint">${state.lastBackup?'Last export: '+esc(new Date(state.lastBackup).toLocaleString()):'No backup exported yet.'} Clearing website data can remove your notebook. Keep a backup in Files.</p></section><section class="card settings-card"><h2>Add to your iPhone Home Screen</h2><p>Open this site in Safari. Tap Share, then “Add to Home Screen.” Open it from the new icon and let it load once while online. The app can then open offline after its offline files have downloaded.</p><p id="offline-status" class="status-label">Checking offline availability…</p><button class="secondary" data-action="persist">Request persistent storage</button><p class="hint">iOS decides whether to grant persistent storage. Backups remain the safest way to keep your records.</p></section><section class="card settings-card"><h2>Local means this device</h2><p>There’s no account sync for workout records. Safari, a Home Screen app, and another phone may have separate storage. Import a backup into the one you use for training.</p><p>The website hosts the app itself. iOS does not let a website automatically overwrite a chosen file in Files; use export/import instead.</p></section>`;}
function render(){const route=location.hash.slice(1)||'today';$('#main').innerHTML=({today,program,session,history,settings}[route]||today)();document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.tab===(route==='session'?'today':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route==='settings')offlineStatus();}
async function confirm(title,copy,ok='Continue'){const d=$('#confirm');$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;$('#confirm-ok').textContent=ok;d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='confirm'),{once:true}));}
async function clearDraftIfNeeded(){return !state.draft||await confirm('Replace your draft?','You have an unfinished session. Replacing it discards its unsaved workout draft. Export a backup first if you want to keep a copy.','Replace draft');}
function updateProgress(){if(!state.draft)return;$('#set-count').textContent=`${completedSets(state.draft)} / ${countSets(state.draft)} sets checked`;$('#progress-bar').style.width=completedSets(state.draft)/Math.max(1,countSets(state.draft))*100+'%';}
function timerText(){const seconds=Math.max(0,Math.ceil((restUntil-Date.now())/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
setInterval(()=>{if($('#rest-time'))$('#rest-time').textContent=timerText();},500);
$('#main').addEventListener('input',event=>{const t=event.target,w=state.draft;if(!w)return;if(t.dataset.field){if(t.value!==''&&(!/^\d+(\.\d+)?$/.test(t.value)||Number(t.value)>10000||(t.dataset.field==='reps'&&(!Number.isInteger(Number(t.value))||Number(t.value)<1)))){t.setCustomValidity('Enter a valid positive number (up to 10000).');return;}t.setCustomValidity('');const s=w.exercises[Number(t.dataset.e)].sets[Number(t.dataset.s)];s[t.dataset.field]=t.value;if(t.dataset.field==='reps'&&!t.value){s.done=false;const row=t.closest('.set-row');row.classList.remove('completed');row.querySelector('button').setAttribute('aria-pressed','false');updateProgress();}}else if(t.id==='session-notes')w.notes=t.value;else if(t.id==='workout-name'){if(!t.value.trim())return;w.name=t.value.trim();}else if(t.id==='workout-date'){if(!validDate(t.value))return;w.date=t.value;}else return;save().catch(()=>{});});
$('#main').addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,w=state.draft,e=w?.exercises[Number(b.dataset.e)];try{
if(a==='start'){if(!await clearDraftIfNeeded())return;state.draft=createWorkout(programs.find(p=>p.id===b.dataset.id),state.history,uid(),localDate());await save();location.hash='session';render();}
if(a==='resume'){location.hash='session';}
if(a==='leave'){location.hash='today';}
if(a==='check'){const s=e.sets[Number(b.dataset.s)];if(!s.done&&(!s.reps||Number(s.reps)<1)){toast('Enter reps before checking this set.');return;}if(!s.done&&s.weight===''&&e.mode!=='bodyweight'){toast('Enter a weight (or assistance) first.');return;}s.done=!s.done;b.setAttribute('aria-pressed',s.done);b.closest('.set-row').classList.toggle('completed',s.done);updateProgress();await save();}
if(a==='add-set'){e.sets.push({weight:e.sets.at(-1)?.weight||'',reps:'',done:false});await save();render();}
if(a==='remove-set'){if(e.sets.at(-1).done&&!await confirm('Remove completed set?','This removes the last set from this draft.','Remove set'))return;e.sets.pop();await save();render();}
if(a==='remove-exercise'){if(!await confirm('Remove exercise?',`Remove ${e.name} and its sets from this session?`,'Remove'))return;w.exercises.splice(Number(b.dataset.e),1);await save();render();}
if(a==='add-exercise'){const name=prompt('Exercise name');if(!name?.trim())return;w.exercises.push(exercise(name.trim().slice(0,100),2,8,12));await save();render();}
if(a==='timer'){restUntil=Number(b.dataset.seconds)?Date.now()+Number(b.dataset.seconds)*1000:0;$('#rest-time').textContent=timerText();}
if(a==='finish'){if(!$('#workout-date').reportValidity()||!$('#workout-name').value.trim()||![...$('#main').querySelectorAll('input')].every(i=>i.reportValidity()))return;if(!completedSets(w)){toast('Complete at least one set before finishing.');return;}if(!await confirm('Finish this session?',`${completedSets(w)} of ${countSets(w)} sets are checked. Your session will be saved to History.`,'Save session'))return;const record=clone(w);const index=state.history.findIndex(x=>x.id===record.id);if(index>=0)state.history[index]=record;else state.history.push(record);state.draft=null;await save();restUntil=0;location.hash='history';toast('Session saved. Nice work.');}
if(a==='discard'){if(!await confirm('Discard this draft?','This removes the current draft. Previously saved history stays in your notebook.','Discard draft'))return;state.draft=null;await save();location.hash='today';}
if(a==='edit'){if(!await clearDraftIfNeeded())return;state.draft=clone(state.history.find(x=>x.id===b.dataset.id));await save();location.hash='session';}
if(a==='delete'){if(!await confirm('Delete saved session?','Export a backup first if you want to keep a copy. This cannot be undone.','Delete session'))return;state.history=state.history.filter(x=>x.id!==b.dataset.id);await save();render();}
if(a==='export')await exportBackup();
if(a==='import')$('#backup-file').click();
if(a==='persist'){const granted=await navigator.storage?.persist?.();toast(granted?'Persistent storage granted. Keep exporting backups.':'Storage request not granted. Keep regular backups.');}
}catch(error){toast('Could not complete that action. '+error.message);}});
function downloadBackup(file){const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function exportBackup(){const time=new Date().toISOString(),backup={...clone(state),lastBackup:time};const file=new File([JSON.stringify(backup,null,2)],`healthspan-training-${localDate()}.json`,{type:'application/json'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Healthspan training backup'});}catch(error){if(error.name==='AbortError')return;downloadBackup(file);}}else downloadBackup(file);state.lastBackup=time;try{await save();}catch{}if(location.hash==='#settings')render();toast('Backup export requested. Keep the file in Files.');}
$('#main').addEventListener('change',async event=>{if(event.target.id!=='backup-file')return;const file=event.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Backup is too large (20 MB maximum).');const incoming=validateBackup(JSON.parse(await file.text()));const added=incoming.history.filter(w=>!state.history.some(x=>x.id===w.id)).length;if(!await confirm('Import this notebook?',`Add ${added} new sessions. Existing session IDs are kept. ${incoming.draft?(state.draft?'Your current draft will be kept.':'The backup draft will be restored.'):'No draft in this backup.'}`,'Import'))return;state.history=mergeHistory(state.history,incoming.history);if(!state.draft&&incoming.draft)state.draft=incoming.draft;await save();render();toast(`Imported ${added} sessions.`);}catch(error){toast('Import failed: '+error.message);}finally{if($('#backup-file'))$('#backup-file').value='';}});
let offlineReady=false;
async function offlineStatus(){if(!$('#offline-status'))return;try{const keys=await caches.keys();offlineReady=keys.some(k=>k.startsWith('lift-log-shell-'));}catch{}if($('#offline-status'))$('#offline-status').textContent=offlineReady?'Offline app files downloaded on this browser.':'Offline files are not ready yet. Stay online and reopen Settings shortly.';}
window.addEventListener('hashchange',()=>{render();scrollTo(0,0);});
await openDB();render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;offlineStatus();}).catch(()=>{if($('#offline-status'))$('#offline-status').textContent='Offline setup failed. Reopen online to try again.';});}
